--
-- Data for Name: fks_professional_services; Type: TABLE DATA; Schema: public; Owner: folks
--

INSERT INTO public.fks_professional_services (professional_id, service_id, price, is_active, created_at, updated_at)
SELECT p.professional_id, s.service_id, s.base_price AS price, 1 AS is_active, CAST(TO_CHAR(CURRENT_DATE, 'yyyy-mm-dd') || ' 00:00:00' AS TIMESTAMP) AS created_at, NULL
  FROM public.fks_professionals p
  JOIN public.fks_services s ON p.professional_id BETWEEN 1 + ((s.service_id - 1) * 8) AND 1 + ((s.service_id - 1) * 8) + 7
 WHERE p.professional_id BETWEEN 1 AND 552
   AND s.service_id BETWEEN 1 AND 69
 ORDER BY s.service_id, p.professional_id;
 

